import{_ as o,o as d,c as t,ae as c}from"./chunks/framework.BtS_DK-n.js";const p=JSON.parse('{"title":"帧同步与游戏房","description":"","frontmatter":{},"headers":[],"relativePath":"rooms/frame-sync-game-room.md","filePath":"rooms/frame-sync-game-room.md","lastUpdated":null}'),a={name:"rooms/frame-sync-game-room.md"};function r(n,e,l,i,s,m){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="帧同步与游戏房" tabindex="-1">帧同步与游戏房 <a class="header-anchor" href="#帧同步与游戏房" aria-label="Permalink to &quot;帧同步与游戏房&quot;">​</a></h1><p><code>game_room</code>（<code>GameRoom</code>）继承 <code>FrameSyncRoom</code>，在固定帧率下收集各客户端 <strong><code>input</code></strong> 消息、驱动 <code>onFrameUpdate</code> / <code>onFrameSync</code>，并通过 Schema 状态（<code>MyRoomState</code>）与广播消息同步表现。该房间通常由 <a href="./rooms/matchmaking.html">匹配与开房</a> 在组局成功后创建，也可在开发阶段自行 <code>joinOrCreate(&quot;game_room&quot;, options)</code> 调试。</p><h2 id="创建选项-oncreate-define" tabindex="-1">创建选项（<code>onCreate</code> / <code>define</code>） <a class="header-anchor" href="#创建选项-oncreate-define" aria-label="Permalink to &quot;创建选项（`onCreate` / `define`）&quot;">​</a></h2><p>在 <code>app.config.ts</code> 中 <code>game_room</code> 默认传入：</p><ul><li><code>fps</code>：目标帧率，默认 <strong>20</strong>。</li><li><code>recordFrames</code>：是否记录帧数据（回放用），默认 <strong>false</strong>。</li></ul><p>匹配创建房间时还会传入 <code>matchId</code>、<code>playersPerMatch</code>、<code>queueKey</code> 或 <code>partyId</code> 等；其中 <strong><code>playersPerMatch</code> 会写入 <code>maxClients</code></strong>，以约束一局人数上限。</p><h2 id="加入房间-onjoin" tabindex="-1">加入房间（<code>onJoin</code>） <a class="header-anchor" href="#加入房间-onjoin" aria-label="Permalink to &quot;加入房间（`onJoin`）&quot;">​</a></h2><p>除 JWT 外，推荐携带匹配下发的字段（与 <code>match:found.joinOptions</code> 对齐）：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>matchId</code></td><td>对局 ID，用于重连校验与 Redis 重连键命名空间。</td></tr><tr><td><code>seatIndex</code></td><td>座位号。</td></tr><tr><td><code>reconnectKey</code></td><td>与断线时服务端生成的密钥一致时，可恢复同一逻辑玩家。</td></tr><tr><td><code>demoUserId</code></td><td>可选；用于同一 JWT 多开测试时区分不同玩家 ID。</td></tr></tbody></table><p>加入成功后，服务端可能下发：</p><ul><li><strong><code>frameSync</code></strong>：<code>currentFrame</code>、<code>targetFPS</code>。</li><li><strong><code>reconnect:ok</code></strong>：重连或去重成功后。</li><li>其它客户端会收到 <strong><code>playerJoined</code></strong> 等（见下文）。</li></ul><h2 id="客户端-→-服务端消息" tabindex="-1">客户端 → 服务端消息 <a class="header-anchor" href="#客户端-→-服务端消息" aria-label="Permalink to &quot;客户端 → 服务端消息&quot;">​</a></h2><h3 id="input-帧输入" tabindex="-1"><code>input</code>（帧输入） <a class="header-anchor" href="#input-帧输入" aria-label="Permalink to &quot;`input`（帧输入）&quot;">​</a></h3><p>由 <code>FrameSyncRoom</code> 注册，payload 建议包含：</p><ul><li><code>inputs</code>：任意结构，由游戏逻辑解释（示例中支持 <code>move</code>、<code>attack</code>、<code>jump</code>）。</li><li><code>frame</code>：可选，指定输入所属帧；不传则使用服务端当前帧。</li></ul><p>服务端每帧合并各 <code>clientId</code> 的最新一条待处理输入，在 <code>onFrameUpdate</code> 中交给 <code>GameRoom.processPlayerInput</code> 等逻辑。</p><h3 id="chat" tabindex="-1"><code>chat</code> <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;`chat`&quot;">​</a></h3><p>简单广播聊天：服务端向 <strong>除发送者以外</strong> 的客户端广播 <code>chat</code>，body 含 <code>clientId</code>、<code>message</code>。</p><h2 id="服务端-→-客户端消息-常见" tabindex="-1">服务端 → 客户端消息（常见） <a class="header-anchor" href="#服务端-→-客户端消息-常见" aria-label="Permalink to &quot;服务端 → 客户端消息（常见）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>消息</th><th>说明</th></tr></thead><tbody><tr><td><code>frameSync</code></td><td>当前帧号与目标 FPS（加入时）。</td></tr><tr><td><code>playerJoined</code></td><td>新玩家加入，<code>sessionId</code>、<code>playerCount</code>。</td></tr><tr><td><code>playerLeft</code></td><td>玩家离开（或超时移除后），含 <code>playerCount</code>。</td></tr><tr><td><code>playerOnline</code> / <code>playerOffline</code></td><td>重连恢复或异常断线进入重连窗口时。</td></tr><tr><td><code>playerAction</code></td><td>示例逻辑中移动、攻击、跳跃等操作的广播。</td></tr><tr><td><code>reconnect:ok</code></td><td>重连或同 <code>userId</code> 去重成功。</td></tr></tbody></table><h2 id="断线重连" tabindex="-1">断线重连 <a class="header-anchor" href="#断线重连" aria-label="Permalink to &quot;断线重连&quot;">​</a></h2><ul><li>非自愿离开（<code>consented === false</code>）时，玩家会被标记为离线，并进入 <strong><code>MATCH_RECONNECT_WINDOW_MS</code></strong> 毫秒的重连窗口（默认 <strong>15000</strong>，可通过环境变量覆盖）。</li><li>窗口内使用 <strong>同一 <code>userId</code> + 匹配下发的 <code>reconnectKey</code>（及一致的 <code>matchId</code>）</strong> 再次加入，可迁移会话并收到 <code>reconnect:ok</code>。</li><li>重连密钥会尝试写入 Redis（<code>mm:reconnect:{matchId}:{userId}</code>），便于多实例扩展；Redis 不可用时仍可使用进程内 <code>pendingReconnect</code>。</li></ul><h2 id="framesync-基类要点" tabindex="-1"><code>FrameSync</code> 基类要点 <a class="header-anchor" href="#framesync-基类要点" aria-label="Permalink to &quot;`FrameSync` 基类要点&quot;">​</a></h2><p><code>src/utils/FrameSync.ts</code> 中的 <code>FrameSyncManager</code>：</p><ul><li>使用 <code>setInterval</code> 按 <code>targetFPS</code> 驱动 <code>tick</code>。</li><li><code>maxFrameDelay</code> 用于告警帧耗时过长（默认 100ms）。</li><li><code>recordFrames</code> 为 true 时会保留近期帧数据（有长度上限，防止内存无限增长）。</li></ul><p>子类需实现 <code>onFrameUpdate</code>、<code>onFrameSync</code>（<code>GameRoom</code> 中已更新 <code>state.frame</code> 与示例属性）。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./rooms/state.html">状态同步（Schema）</a>（<code>MyRoomState</code>、<code>Player</code> 字段）</li><li><a href="./reference/protocol.html">消息协议总表</a></li></ul>',28)])])}const u=o(a,[["render",r]]);export{p as __pageData,u as default};
